3 = 270 degrees
@param int $degree
@param $asianFont
@throw ExceptionCommand
@return int

code:
private function rotationConvertFromDegree($degree, $asianFont)
    {
        switch ($degree) {
            case 90:
                if ($asianFont) {
                    return 5;
                }
                return 1;
            case 180:
                if ($asianFont) {
                    return 6;
                }
                return 2;
            case 270:
                if ($asianFont) {
                    return 7;
                }
                return 3;
            case 0:
                if ($asianFont) {
                    return 4;
                }
                return 0;
            default:
                throw ExceptionCommand::invalidDegree($degree);
        }

    }

