public int getAllCookieValues(String name, List<String> list) {
        int added = 0;
        if (0 < this.parsedList.size() && null != name) {
            for (HttpCookie cookie : this.parsedList) {
                if (name.equals(cookie.getName())) {
                    list.add(cookie.getValue());
                }
            }
        }
        return added;
