    {
        $curl = $request->getCurl();
        $response = $request->getResponse();

        $response->setErrorCode($errorCode)
                 ->setErrorMessage($curl->getErrorMessage());
        if ($errorCode === CURLE_OK) {
            $this->hydrateResponseFromCurl($response, $curl);
