public static function preprocess($url_parsed) {
        if (preg_match('/\.(\w+)$/i', $url_parsed['path'], $matches) == 1) {
            $extension = strtolower($matches[1]);
            if ($extension == 'ogv') $extension = 'ogg';
            return array(
                'filetype' => $extension,
                'url' => URL::build($url_parsed),
            );
        }
        return FALSE;
    }

