comment:
@param null|integer|array $data
@param string $sort
@return array

if $data is null - collect all migrations
if $data is array - it contains migrationPaths
if $data is integer - collect all migrations but $limit list by $data value

code:
protected function getNewMigrations( $data = null, $sort = self::SORT_BY_GROUP )
	{
		$migrations = [];

		if( is_numeric( $data ) && (int)$data ) {
			$limit = (int)$data;
		}
		// for cases such as migrate
		else if( !empty( $data ) && is_string( $data ) ) {
			return parent::getNewMigrations();
		}
		else {
			$limit = null;
		}

		/*
		 * if set $migrationPaths from action
		 */
		if( is_array( $data ) ) {
			$migrationPaths = $data;
		}
		/*
		 * set migrationPath and migrationNamespaces from config
		 */
		else {
			$migrationPaths = array_unique( array_merge( ( $this->migrationPath ?? [] ), ( $this->migrationNamespaces ?? [] ), [ $this->defaultMigrationPath ] ) );
		}

		/*
		 * check $migrationPaths and collect subfolders from paths and namespaces
		 */
		foreach( $migrationPaths as $key => $path ) {
			if( $paths = FileHelper::resolvePath( $path, [ 'filter' => '/migration/' ] ) ) {

				foreach( $migrationPaths as $key => $searchPath ) {
					if( $searchPath == $path ) {
						/*
						 * change record such as alias to resolved items with or w/o subfolders
						 */
						array_splice( $migrationPaths, $key, 1, $paths );
						break;
					}
				}

			}
			/*
			 * if not correct - remove from list
			 */
			else {
				unset( $migrationPaths[ $key ] );
			}
		}

		/*
		 * at this moment $this->migrationPath already parsed by BaseMigrateController
		 * and $migrationPaths is resolved result of passed $data
		 * it's need to merge and unique both results
		 */
		if( is_array( $data ) ) {
			$this->migrationPath = array_unique( array_merge( $this->migrationPath, $migrationPaths ) );
		}
		else {
			$this->migrationPath = $migrationPaths;
		}

		foreach( $migrationPaths as $path ) {

			if( is_dir( $path ) ) {
				$files = FileHelper::findFiles( $path, [ 'only' => [ '*.php' ], 'recursive' => false ] );
			}
			else if( is_file( $path ) ) {
				$files = [ $path ];
			}
			else {
				continue;
			}

			if( $files ) {

				$migrationsGroup = [];

				foreach( $files as $file ) {

					if( preg_match( '/(m(\d{6}_?\d{6})\D.*?)\.php$/is', $file, $matches ) && is_file( $file ) ) {

						require_once( $file );

						$class = $matches[1];

						if( $ns = FileHelper::extract_namespace( $file ) ) {
							$class = $ns . '\\' . $class;
						}

						$time = str_replace( '_', '', $matches[2] );

						// @TODO change 'migrations' to something default
						$suffix = preg_replace( '/.*migrations(.*)\.php/', '$1', $file );

						if( !$this->_isApplied( $class ) ) {

							$migrationsGroup[ $time . $suffix ] = $class;

							if( !isset( $this->_migrationsByGroup[ pathinfo( $file )['dirname'] ][ $class ] ) ) {
								$this->_migrationsByGroup[ pathinfo( $file )['dirname'] ][ $class ] = $file;
								$this->_migrations[ $class ]                                        = $file;
							}

						}
					}
				}

				// time sort
				ksort( $migrationsGroup );
				$migrations = array_merge( $migrations, $migrationsGroup );
			};

		}

		$migrations = array_unique( $migrations );

		if( $sort == self::SORT_COMMON ) {
			ksort( $migrations );
		}

		if( (int)$limit > 0 ) {
			$migrations = array_slice( $migrations, 0, $limit );
		}

		return $migrations;
	}

