	if err != nil {
		return "", err
	}
	cmd.Stdout = &buf
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", errwrap.Wrapf(fmt.Sprintf("%q: {{err}}", stderr.String()), err)
	}

	return buf.String(), nil
}

