public function getQueryParams(UriInterface $uri, $exclude = ['sig'], $params = [])
    {
        parse_str($uri->getQuery(), $params);
        foreach ($exclude as $excludedParam) {
            if (array_key_exists($excludedParam, $params)) {
                unset($params[$excludedParam]);
            }
        }
        return $params;
    }

