对需要加密的明文进行填充补位

@param string $text 需要进行填充补位操作的明文
@return string 补齐明文字符串

code:
protected function pkcs7Encode($text)
    {
        $size = 32;
        $textLength = strlen($text);

        // 计算需要填充的位数
        $amountToPad = $size - ($textLength % $size);
        if ($amountToPad == 0) {
            $amountToPad = $size;
        }

        // 获得补位所用的字符
        $padChr = chr($amountToPad);
        $tmp = '';
        for ($index = 0; $index < $amountToPad; $index++) {
            $tmp .= $padChr;
        }
        return $text . $tmp;
    }

