检测域名路由
@access public
@param  string       $url      访问地址
@param  bool         $completeMatch   路由是否完全匹配
@return Dispatch|false

code:
public function check($url, $completeMatch = false)
    {
        // 检测别名路由
        $result = $this->checkRouteAlias($url);

        if (false !== $result) {
            return $result;
        }

        // 检测URL绑定
        $result = $this->checkUrlBind($url);

        if (!empty($this->option['append'])) {
            $request->setRouteVars($this->option['append']);
            unset($this->option['append']);
        }

        if (false !== $result) {
            return $result;
        }

        return parent::check($url, $completeMatch);
    }

