            'Kindle/1'    => 'amazon_kindle_ver1',
            'Kindle/2'    => 'amazon_kindle2_ver1',
            'Kindle/3'    => 'amazon_kindle3_ver1',
            'Kindle Fire' => 'amazon_kindle_fire_ver1',
