code:
public function getConfigPaths( $dbtype )
	{
		$confpaths = array();

		foreach ( $this->_manifests as $path => $manifest )
		{
			if ( isset( $manifest['config'][$dbtype] ) )
			{
				foreach ( $manifest['config'][$dbtype] as $paths ) {
					$confpaths[] = $path . DIRECTORY_SEPARATOR . $paths;
				}
			}
		}

		return $confpaths;
	}

