private static function clearName($string, $removeWords) {
		$string = str_replace ( ' ', '-', $string );
		$string = preg_replace ( '/[^A-Za-z0-9\-]/', '', $string );
		foreach ( $removeWords as $word ) {
			$string = str_replace ( $word, '', $string );
		}
		$string = substr ( $string, 0, 29 );
		return $string;
	}

