public function setAttributes(array $attributes)
    {
        $this->attributes = array_merge($this->attributes, $attributes);

        $set = array();
        foreach ($attributes as $name => $value) {
            if ($name == 'status') {
                $this->update($value);
                continue;
            }
            $set[$name] = $value;
        }

        return call_user_func(array($this->client, 'hmset'), $this->getHashKey(), $set);
    }

