        $objectManager->persist($newObject);
        $objectManager->flush();

        $this->addFlash(
            'sonata_flash_success',
            $this->admin->trans('flash_duplicate_success')
        );

        return new RedirectResponse($this->admin->generateObjectUrl('edit', $newObject));
    }

