code:
public function extractTags(DataObject $object, $field = 'Content') {
		if (!$object->hasExtension('TaggableExtension')) {
			return array();
		}
		$content = $object->$field;

		if (preg_match_all('/#([a-z0-9_-]+)/is', $content, $matches)) {
			$object->tag($matches[1], true);
		}

		return $object->Tags();
	}

