comment:
Checks, if a file is svg (needed when xml declaration is missing).

@param AbstractLocalImage $image

@return bool

code:
private function isSvg(AbstractLocalImage $image)
    {
        $dom = new \DOMDocument();
        $content = $image->getContent();
        if (null === $content) {
            return false;
        }
        if ($dom->loadXML($content)) {
            $root = $dom->childNodes->item(0);
            if (null === $root) {
                return false;
            }
            if ('svg' == $root->localName && 'http://www.w3.org/2000/svg' == $root->namespaceURI) {
                return true;
            }
        }

        return false;
    }

